package vn.smartfarm.iot.irrigation;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=false","smartfarm.irrigation.circuit-demo-enabled=true"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class CircuitValveControlTest {
 @Autowired CircuitValveControl service;@Autowired IrrigationCircuits circuits;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired MockMvc mvc;@MockitoBean CircuitValveTransport transport;
 UUID boot=UUID.fromString("87000000-0000-4000-8000-000000000001");Map<String,Long> baseline;
 @BeforeEach void setup(){cleanup();baseline=new HashMap<>();for(String table:List.of("pump_command","watering_run","irrigation_demo_command","circuit_valve_status"))baseline.put(table,jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Long.class));
  for(int i=1;i<=2;i++){
   jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES(?,?,'AREA001','SOIL',2)","CDSOIL"+i,"Soil");
   for(int j=1;j<=3;j++)jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES(?,?,'SOIL_MOISTURE','%')","CDSOIL"+i,"SOIL"+j);
   jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES(?,?,'AREA001',?,'SIMULATOR',30,35)","CDZONE"+i,"Zone","CDSOIL"+i);
  }
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('CDWATER','Water','AREA001','WATER',2)");jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('CDWATER','LOW','WATER_PRESENT','boolean'),('CDWATER','FLOW','FLOW_RATE','L/min')");
  for(int i=1;i<=2;i++)jdbc.update("INSERT INTO irrigation_circuit(circuit_id,name,zone_id,zone_revision,controller_id,valve_id,pump_id,water_node_id,low_channel_id,flow_channel_id,expected_source) VALUES(?,?,?,1,?,?,'PUMP01','CDWATER','LOW','FLOW','SIMULATOR')","CD"+i,"Circuit","CDZONE"+i,"IRRIGATION"+(87+i),"VALVE"+(87+i));
  when(transport.circuitValveConnected(anyString())).thenReturn(true);receive("CD1",packet("CD1",1,0,"CLOSED",boot));receive("CD2",packet("CD2",1,0,"CLOSED",boot));
 }
 void cleanup(){for(String t:List.of("circuit_demo_command","circuit_demo_status","circuit_demo_boot","circuit_demo_gate"))jdbc.update("DELETE FROM "+t+" WHERE valve_id IN ('VALVE88','VALVE89')");jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id IN ('CD1','CD2')");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id IN ('CDZONE1','CDZONE2')");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('CDSOIL1','CDSOIL2','CDWATER')");}
 @AfterEach void after(){for(var e:baseline.entrySet())assertEquals(e.getValue(),jdbc.queryForObject("SELECT COUNT(*) FROM "+e.getKey(),Long.class),e.getKey());cleanup();}
 ObjectNode packet(String id,long seq,long last,String gpio,UUID b){var c=circuits.find(id);var p=mapper.createObjectNode().put("schemaVersion",1).put("controlProfile",CircuitValveControl.PROFILE).put("controllerId",c.controllerId()).put("actuatorId",c.valveId()).put("circuitId",id).put("circuitRevision",c.revision()).put("zoneId",c.zoneId()).put("zoneRevision",c.zoneRevision()).put("bootId",b.toString()).put("sequence",seq).put("timestamp",Instant.now().toString()).put("dataSource","SIMULATOR").put("feedbackState",gpio).put("gpioState",gpio).put("reason",gpio.equals("OPEN")?"COMMAND_OPEN":"COMMAND_CLOSE").put("demoEnabled",true).put("lastOrdinal",last);p.putObject("positionFeedback").put("version",1).put("enabled",true).put("state",gpio).putNull("fault");return p;}
 void receive(String id,ObjectNode p){service.receive(CircuitValveControl.topic(circuits.find(id).valveId(),p.has("commandId")?"ack":"status"),p.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),false);}
 CircuitValveControl.Request request(String id,String action){var s=service.snapshot(id);return new CircuitValveControl.Request(UUID.randomUUID(),action,action.equals("OPEN")?5:null,s.latest().bootId(),s.config().revision(),s.config().zoneRevision(),Instant.now());}
 CircuitValveControl.Command open(String id){return service.create(id,request(id,"OPEN"));}
 void ack(String id,CircuitValveControl.Command c,long seq){receive(id,packet(id,seq,c.ordinal(),c.action().equals("OPEN")?"OPEN":"CLOSED",c.bootId()).put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action",c.action()).put("result","EXECUTED").putNull("errorCode"));}
 @Test void tracksBeforePublishAndKeepsEachValveIsolated()throws Exception{
  doAnswer(a->{var p=mapper.readTree((byte[])a.getArgument(1));assertEquals("PENDING",service.lookup("CD1",UUID.fromString(p.path("commandId").asText())).state());assertEquals("CIRCUIT_LED_DEMO",p.path("controlProfile").asText());assertEquals("VALVE88",a.getArgument(0));assertEquals(1,p.path("circuitRevision").asInt());return null;}).when(transport).publishCircuitValve(anyString(),any());
  assertEquals("SENT",open("CD1").state());assertTrue(service.snapshot("CD2").readyToOpen());assertTrue(service.snapshot("CD2").commands().isEmpty());assertFalse(service.snapshot("CD1").readyToOpen());
 }
 @Test void duplicateIdDoesNotPublishAgainAndDifferentIntentConflicts()throws Exception{var r=request("CD1","OPEN");var c=service.create("CD1",r);assertEquals(c.commandId(),service.create("CD1",r).commandId());verify(transport,times(1)).publishCircuitValve(eq("VALVE88"),any());assertThrows(ResponseStatusException.class,()->service.create("CD2",r));assertThrows(ResponseStatusException.class,()->service.create("CD1",new CircuitValveControl.Request(r.requestId(),"CLOSE",null,r.expectedBootId(),1,1,r.requestedAt())));}
 @Test void uncertainPublishStaysTrackedWithoutAutomaticRetry()throws Exception{doThrow(new IllegalStateException()).when(transport).publishCircuitValve(anyString(),any());var r=request("CD1","OPEN");assertEquals("PUBLISH_UNCERTAIN",service.create("CD1",r).state());service.create("CD1",r);verify(transport,times(1)).publishCircuitValve(anyString(),any());assertFalse(service.snapshot("CD1").readyToOpen());}
 @Test void ackDuringPublishIsNotOverwrittenAndNeverChangesLatestStatus()throws Exception{doAnswer(a->{var c=service.snapshot("CD1").commands().getFirst();ack("CD1",c,2);return null;}).when(transport).publishCircuitValve(anyString(),any());var c=open("CD1");assertEquals("EXECUTED",c.state());assertEquals(1,service.snapshot("CD1").latest().sequence());assertEquals("CLOSED",service.snapshot("CD1").latest().gpioState());assertFalse(service.snapshot("CD1").readyToOpen());}
 @Test void closeFencesDelayedOpenAndNeedsStatusAfterAck(){var delayed=request("CD1","OPEN");var close=service.create("CD1",request("CD1","CLOSE"));ack("CD1",close,3);assertThrows(ResponseStatusException.class,()->service.create("CD1",delayed));assertFalse(service.snapshot("CD1").readyToOpen());receive("CD1",packet("CD1",4,close.ordinal(),"CLOSED",boot));jdbc.update("UPDATE circuit_demo_gate SET close_fence_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE valve_id='VALVE88'");assertTrue(service.snapshot("CD1").readyToOpen());}
 @Test void lateOpenAckCannotOverwriteNewerClosedStatus(){var on=open("CD1");var off=service.create("CD1",request("CD1","CLOSE"));receive("CD1",packet("CD1",5,off.ordinal(),"CLOSED",boot));ack("CD1",on,2);assertEquals(off.ordinal(),service.snapshot("CD1").latest().lastOrdinal());assertEquals("CLOSED",service.snapshot("CD1").latest().gpioState());}
 @Test void pendingCommandOutsideTwentyStillBlocksOpen(){open("CD1");for(int i=0;i<22;i++)service.create("CD1",request("CD1","CLOSE"));jdbc.update("UPDATE circuit_demo_gate SET close_fence_at=NULL WHERE valve_id='VALVE88'");assertEquals(20,service.snapshot("CD1").commands().size());assertFalse(service.snapshot("CD1").readyToOpen());}
 @Test void stalePositionUnknownAndWrongBootRejectOpenButStaleCloseIsAllowed(){jdbc.update("UPDATE circuit_demo_status SET observed_at=CURRENT_TIMESTAMP-INTERVAL '20 seconds' WHERE valve_id='VALVE88'");assertThrows(ResponseStatusException.class,()->open("CD1"));assertEquals("SENT",service.create("CD1",request("CD1","CLOSE")).state());var r=request("CD2","OPEN");assertThrows(ResponseStatusException.class,()->service.create("CD2",new CircuitValveControl.Request(r.requestId(),r.action(),5,UUID.randomUUID(),1,1,r.requestedAt())));}
 @Test void changedZoneStopsOpenAndAllowsClose(){jdbc.update("UPDATE irrigation_zone SET revision=2 WHERE zone_id='CDZONE1'");assertFalse(service.snapshot("CD1").readyToOpen());assertEquals("SENT",service.create("CD1",request("CD1","CLOSE")).state());}
 @Test void configurationEditsAndSharingAreBlockedWhileCommandUnconfirmed(){open("CD1");var current=mapper.valueToTree(circuits.find("CD1"));assertThrows(ResponseStatusException.class,()->circuits.update("CD1",current));var second=(ObjectNode)mapper.valueToTree(circuits.find("CD2"));second.put("controllerId","IRRIGATION88");assertThrows(ResponseStatusException.class,()->circuits.update("CD2",second));}
 @Autowired vn.smartfarm.iot.zones.IrrigationZones zones;
 @Test void zoneEditsUseSameCommandGateAndRequireConfirmedClosed(){
  var body=mapper.createObjectNode().put("zoneId","CDZONE1").put("name","Edited zone").put("areaId","AREA001").put("soilNodeId","CDSOIL1").put("expectedSource","SIMULATOR").put("dryThreshold",30).put("wetThreshold",35).put("revision",1);body.set("channelIds",mapper.valueToTree(List.of("SOIL1","SOIL2","SOIL3")));
  open("CD1");assertThrows(ResponseStatusException.class,()->zones.update("CDZONE1",body));var close=service.create("CD1",request("CD1","CLOSE"));receive("CD1",packet("CD1",4,close.ordinal(),"CLOSED",boot));assertEquals(2,zones.update("CDZONE1",body).config().revision());assertFalse(service.snapshot("CD1").readyToOpen());
 }
 @Test void freshClosedCanRemapButSameBootCannotAdoptNewRevision(){var current=(ObjectNode)mapper.valueToTree(circuits.find("CD1"));current.put("name","Renamed");assertEquals(2,circuits.update("CD1",current).revision());receive("CD1",packet("CD1",2,0,"CLOSED",boot));assertEquals(1,service.snapshot("CD1").latest().config().revision());UUID next=UUID.randomUUID();receive("CD1",packet("CD1",0,0,"CLOSED",next));assertTrue(service.snapshot("CD1").readyToOpen());}
 @Test void duplicateStatusDoesNotRefreshReceiptAndRetiredBootCannotReturn(){var before=service.snapshot("CD1").latest();receive("CD1",packet("CD1",1,0,"CLOSED",boot));assertEquals(before.receivedAt(),service.snapshot("CD1").latest().receivedAt());UUID next=UUID.randomUUID();receive("CD1",packet("CD1",0,0,"CLOSED",next));receive("CD1",packet("CD1",20,0,"CLOSED",boot));assertEquals(next,service.snapshot("CD1").latest().bootId());}
 @Test void unknownOrOtherValveOrdinalIsRejected(){var c=open("CD1");assertThrows(IllegalArgumentException.class,()->receive("CD2",packet("CD2",2,c.ordinal(),"CLOSED",boot)));assertThrows(IllegalArgumentException.class,()->receive("CD1",packet("CD1",2,c.ordinal()+500,"CLOSED",boot)));}
 @Test void retainedWrongSourceMonitorAndMissingFeedbackAreRejected(){var p=packet("CD1",2,0,"CLOSED",boot);assertThrows(IllegalArgumentException.class,()->service.receive(CircuitValveControl.topic("VALVE88","status"),p.toString().getBytes(),true));p.put("dataSource","PHYSICAL");assertThrows(IllegalArgumentException.class,()->receive("CD1",p));p.put("dataSource","SIMULATOR").put("controlProfile","IRRIGATION_MONITOR_ONLY");assertThrows(IllegalArgumentException.class,()->receive("CD1",p));p.put("controlProfile",CircuitValveControl.PROFILE).remove("positionFeedback");assertThrows(IllegalArgumentException.class,()->receive("CD1",p));}
 @Test void positionFaultOnlyClearsAfterNewCloseStatus(){var p=packet("CD1",2,0,"CLOSED",boot).put("reason","POSITION_FAULT");((ObjectNode)p.get("positionFeedback")).put("fault","POSITION_LOST");receive("CD1",p);receive("CD1",packet("CD1",3,0,"CLOSED",boot));assertNotNull(service.snapshot("CD1").latest().positionFeedback().fault());var c=service.create("CD1",request("CD1","CLOSE"));receive("CD1",packet("CD1",4,c.ordinal(),"CLOSED",boot));assertNull(service.snapshot("CD1").latest().positionFeedback().fault());}
 @Test void wrongBootAckAndCrossCircuitLookupDoNotConfirmCommand(){var c=open("CD1");var p=packet("CD1",2,c.ordinal(),"OPEN",UUID.randomUUID()).put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","OPEN").put("result","EXECUTED").putNull("errorCode");receive("CD1",p);assertEquals("SENT",service.lookup("CD1",c.commandId()).state());assertThrows(ResponseStatusException.class,()->service.lookup("CD2",c.commandId()));}
 @Test void invalidDurationDisconnectedAndStaleHttpCannotPublish(){var r=request("CD1","OPEN");for(int n:new int[]{0,31})assertThrows(ResponseStatusException.class,()->service.create("CD1",new CircuitValveControl.Request(UUID.randomUUID(),"OPEN",n,boot,1,1,Instant.now())));assertThrows(ResponseStatusException.class,()->service.create("CD1",new CircuitValveControl.Request(r.requestId(),"OPEN",5,boot,1,1,Instant.now().minusSeconds(30))));when(transport.circuitValveConnected(anyString())).thenReturn(false);assertThrows(ResponseStatusException.class,()->open("CD1"));verifyNoMoreInteractionsAfterReads();}
 void verifyNoMoreInteractionsAfterReads(){try{verify(transport,never()).publishCircuitValve(anyString(),any());}catch(Exception e){throw new RuntimeException(e);}}
 @Test void independentValvesMayOpenButConcurrentSameValveHasOnePublish()throws Exception{var a=request("CD1","OPEN");var b=request("CD1","OPEN");var executor=Executors.newFixedThreadPool(2);try{var jobs=executor.invokeAll(List.<Callable<Boolean>>of(()->{try{service.create("CD1",a);return true;}catch(ResponseStatusException e){return false;}},()->{try{service.create("CD1",b);return true;}catch(ResponseStatusException e){return false;}}));assertEquals(1,jobs.stream().filter(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).count());}finally{executor.shutdownNow();}assertEquals("SENT",open("CD2").state());verify(transport,times(1)).publishCircuitValve(eq("VALVE88"),any());verify(transport,times(1)).publishCircuitValve(eq("VALVE89"),any());}
 @Test void httpReadAndUnknownFieldValidation()throws Exception{mvc.perform(get("/api/v1/irrigation-circuits/CD1/control")).andExpect(status().isOk()).andExpect(jsonPath("$.profile").value("CIRCUIT_LED_DEMO")).andExpect(jsonPath("$.readyToOpen").value(true));mvc.perform(post("/api/v1/irrigation-circuits/CD1/control/commands").contentType("application/json").content("{\"extra\":true}")).andExpect(status().isBadRequest());}
}
